package autogradesys.validation;

import java.nio.file.Path;

/**
 * Small helpers shared by the classes that walk through submitted files.
 */
// Generated by Claude (Anthropic); reviewed and adapted by the team
public final class SubmissionFiles {

    private static final String MAC_METADATA_FOLDER = "__MACOSX";

    private SubmissionFiles() {
    }

    /**
     * Hidden files (e.g. macOS "._Q1a.java") and __MACOSX are clutter, not student work.
     *
     * @param relative A path inside a submission; every part of it is checked.
     */
    public static boolean isJunk(Path relative) {
        for (Path part : relative) {
            String name = part.toString();
            if (name.startsWith(".") || name.equals(MAC_METADATA_FOLDER)) {
                return true;
            }
        }
        return false;
    }
}
